import{_ as r,l as i,o as a,c as p,v as o,p as n,x as t,d as s,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"离策略校正","description":"","frontmatter":{"title":"离策略校正","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/off-policy-correction.md","filePath":"llm/off-policy-correction.md","lastUpdated":1789023840000}'),d={name:"llm/off-policy-correction.md"};function _(m,e,E,A,f,u){const l=i("Mermaid");return a(),p("div",null,[e[1]||(e[1]=o('<h1 id="离策略校正" tabindex="-1">离策略校正 <a class="header-anchor" href="#离策略校正" aria-label="Permalink to &quot;离策略校正&quot;">​</a></h1><div class="epigraph"><p>异步生成让一个 batch 混着多个权重版本；校正的是期望算子，不是把 off-policy 假装成 on-policy。</p><footer>—— 对照 IMPALA / V-trace；AReaL、OpenRLHF、verl 对 staleness 与版本号的工程约束</footer></div><p><a href="/llm/truncated-importance-sampling">上一课</a>给出截断比率。缺口是：<strong>系统已经在混合版本时，公式要定义「校正到哪一个 \\(\\pi\\)」，以及不能校正时就丢弃。</strong> 已有异步架构课写时序；本课写算法侧：staleness 上限、重算 logprob、partial rollout。接到 <a href="/llm/ppo-llm">PPO</a> / <a href="/llm/grpo">GRPO</a> 的仍是同一套优势，只是期望的采样分布变了。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同步栅栏：\\(\\pi_{\\mathrm{beh}}=\\pi_{\\mathrm{old}}\\)，IS 近似 1，PPO epoch 造成轻度 off-policy。一步重叠：差一个版本。完全异步：batch 内 \\(\\pi_{\\mathrm{beh}}\\) 不同，甚至一条序列中途换权重。未校正就把梯度当 on-policy，优势的期望不对，长链上表现为莫名崩溃。校正要：每条轨迹带 <code>weight_version</code>，用当前 learner 的 \\(\\pi_\\theta\\) 重前向得 \\(\\log\\pi_\\theta\\)，与存储的 \\(\\log\\pi_{\\mathrm{beh}}\\) 比。</p><p>不能无限校正。版本差过大时 \\(\\rho\\) 几乎全被截断，有效样本为零，应丢弃或限制 \\(\\eta\\)（AReaL 的 staleness）。Partial rollout 接新权重续写，KV 与 logprob 必须重算前缀，否则前半段是旧策略、后半段是新策略，一条轨迹两个行为分布。</p><h3 id="校正不等于可以无限复用" tabindex="-1">校正不等于可以无限复用 <a class="header-anchor" href="#校正不等于可以无限复用" aria-label="Permalink to &quot;校正不等于可以无限复用&quot;">​</a></h3><p>截断 IS 降低方差，不把旧数据变成新 on-policy 数据。复用次数仍应限制。PPO 的 epoch 上限与异步 staleness 是同一类旋钮：用过期轨迹的预算。</p><p><span class="marginnote">RM / 校验器通常只依赖 \\(y\\) 文本，不依赖生成它的版本。要校正的是策略梯度项，不是奖励本身。奖励过期是另一回事（RM 未迭代）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议字段：<code>prompt_id</code>、<code>y</code>、<code>logp_beh</code>、<code>version_beh</code>、<code>truncated</code>。Learner step \\(i\\) 只接受 \\(i-v\\le\\eta\\) 的样本。更新前重算 \\(\\log\\pi_\\theta\\)，得逐步 \\(\\rho_t\\)，截断后进目标。GRPO 的组：同一 prompt 的 \\(G\\) 条最好同版本，否则组内 \\(r\\) 可比、\\(\\rho\\) 不可比，相对优势与 IS 拧在一起。做不到则拆组或降级为 RLOO 单条基线。</p>',11)),(a(),n(h,null,{default:t(()=>[c(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E5%A4%9A%E7%89%88%E6%9C%AC%20rollout%22%5D%20--%3E%20META%5B%22%E6%90%BA%E5%B8%A6%20version%20%E4%B8%8E%20logp_beh%22%5D%0A%20%20META%20--%3E%20STALE%7B%22%E7%89%88%E6%9C%AC%E5%B7%AE%20%E2%89%A4%20%CE%B7%22%7D%0A%20%20STALE%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%22%5D%0A%20%20STALE%20--%3E%7C%E6%98%AF%7C%20RE%5B%22%CF%80_%CE%B8%20%E9%87%8D%E7%AE%97%20logp%22%5D%0A%20%20RE%20--%3E%20IS%5B%22%E6%88%AA%E6%96%AD%20%CF%81%22%5D%0A%20%20IS%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>价值函数若用，应对当前 \\(\\pi_\\theta\\) 重算 \\(V\\)，不要用生成时的 \\(V\\)。GAE 的 \\(\\delta\\) 对过期 \\(V\\) 极敏感。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>V-trace 一类方法把截断后的 \\(\\rho\\) 沿轨迹回传，修正 \\(V\\) 的 off-policy 偏差。LLM 上常简化为：重算 logprob + PPO clip + 丢过期样本。简化成立的前提是 \\(\\eta\\) 小。\\(\\eta\\) 大时，简化不够，应减小异步程度，而不是加大 \\(c\\) 假装校正。</p><p><span class="marginnote">生成引擎量化 / 编译图与训练精度不一致，会造成「假 off-policy」：版本相同，logprob 仍系统偏。见后课训练-推理精度不匹配。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>小规模同步训练不必上本课全套，避免过度设计。推理模型长链才被迫异步。组相对方法对「同组同版本」更苛刻。下一课 rollout 引擎与权重同步，把 version 这条边落到 NCCL / 广播实现，公式在本课已经定完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>混合版本 batch 必须带行为 logprob 与版本号，重算 \\(\\pi_\\theta\\) 再截断 IS。</li><li>staleness 上限 \\(\\eta\\)：校正不动就丢弃。</li><li>GRPO 组内应同版本；partial rollout 要重算前缀。</li><li>奖励通常不校正；过期的是策略项。</li><li>出处：Espeholt 等 IMPALA / V-trace；Fu 等 AReaL；Sheng 等 HybridFlow；OpenRLHF / verl 的版本化实践。</li></ul>',8))])}const g=r(d,[["render",_]]);export{P as __pageData,g as default};
